"""Document and archive the verified frozen research runtime, never respondent data."""
import hashlib,json,sys,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.inference.constants import MODEL_HASH,FEATURES,PROFILE_NAMES
from src.inference.validation import DICTIONARY,DOMAINS
from api.main import create_app
from api.config import Settings
from src.inference.model_loader import load_artifacts
OUT=ROOT/'reports/deployment';RELEASE=ROOT/'release'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def table(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(str(v).replace('|','/') for v in row)+' |' for row in rows)+'\n'
def main():
    assert sha(ROOT/'models/heart_disease_pipeline.joblib')==MODEL_HASH
    artifacts=load_artifacts(Settings());policy=artifacts.policy
    contract='# API contract — research release 1.0.0\n\nThis is the stable contract for future clients. Model and API version: **1.0.0**. The model classifies profiles associated with **existing self-reported CHD/MI in BRFSS 2021**. It is not a diagnosis, future-risk prediction or clinical screening standard.\n\n## Endpoints\n\n'+table(['Method','Endpoint','Request','Response'],[['GET','/health','None','200: {"status":"ok"}'],['GET','/ready','None','200: status ready and model_version; otherwise 503'],['GET','/model-info','None','Safe model family/version, features, profiles, intended use and limitations'],['POST','/predict','Required profile; optional threshold_profile','Prediction result'],['POST','/predict/batch','Required profiles list; optional threshold_profile','Ordered predictions list plus count']])+'\nLiveness alone does not establish model readiness. Startup must verify all supporting hashes and golden vectors before serving. A model/hash mismatch aborts startup. Model-info never returns filesystem paths, secrets, raw rows or classifier objects.\n\n## Profile fields\n\nFields use the unchanged data dictionary and cleaned encoding. No aliases or automatic raw-CDC recoding are supported. All 14 predictors permit omission/null. The profile object itself is required and must be nonempty; one known field with null is sufficient to express unknown information.\n\n'
    rows=[]
    for name in FEATURES:
        row=DICTIONARY[name]
        if name=='bmi':allowed='Numeric BMI 12.00–99.99 (human-readable; never /100)'
        else:
            mapping=json.loads(row['clean_mapping']);labels=json.loads(row['original_labels'])
            allowed='; '.join(str(code)+': '+' / '.join(labels[k] for k,v in mapping.items() if v==code) for code in DOMAINS[name])
        rows.append([name,'number' if name=='bmi' else 'strict integer category',allowed,'Saved training median BMI' if name=='bmi' else 'Explicit __MISSING__ token'])
    contract+=table(['Field','Type','Allowed values','Omitted/null handling'],rows)+'\nNumbers encoded as strings, booleans, category floats, unsupported category codes, non-finite numbers, nested values and unknown fields are rejected rather than mapped to missing. Education and income are excluded; heart_disease, _MICHD, CVDINFR4 and CVDCRHD4 are rejected. Smoking retains the CDC lifetime 100-cigarette distinction; diabetes retains all four categories.\n\n## Request examples (synthetic)\n\n```json\n{"profile":{"sex":1,"bmi":28.5},"threshold_profile":"research_balanced"}\n```\n\n```json\n{"profiles":[{"sex":1},{"sex":2,"bmi":null}],"threshold_profile":"high_sensitivity_80"}\n```\n\nBatch limit defaults to 1,000 (configurable downward). Body limit defaults to 1 MiB and applies to streamed bodies too. Batches validate transactionally: any invalid row rejects the whole batch with an indexed location; there are no partial predictions. Output order equals input order.\n\n## Response\n\n`profile_score` is a number in [0,1]; `classification` is lower_model_association or elevated_model_association; `threshold` is the exact stored research threshold; `threshold_profile` is a supported name; `model_version` is 1.0.0; `model_name` is BRFSS CHD/MI Profile Score; `model_context` supplies the non-diagnostic interpretation. Batch response wraps results as `predictions` and `count`. All successful responses are HTTP 200.\n\nScores are computed with full precision. Classification uses `score >= threshold`. Only JSON score display is rounded to six decimals; do not recompute classification from that rounded score. Golden tolerance is 1e-12 internally and 0.5e-6 + 1e-12 over HTTP.\n\n## Named threshold policies\n\n'+table(['Profile','Exact threshold','Meaning'],[[name,repr(policy['profiles'][name]['threshold']),policy['profiles'][name]['selection_basis']] for name in PROFILE_NAMES])+'\nOmitting threshold_profile selects research_balanced. Arbitrary numeric thresholds and unknown names are rejected. The same input produces identical profile_score and model_version across all profiles; only classification, threshold and threshold_profile can change. These validation-derived operating points are not clinical cutoffs. Default validation recall is 51.27% (2,582 missed positives). The ~80% profile avoids 1,522 misses but adds 10,273 false positives; ~90% avoids 2,052 misses but adds 18,423 false positives. Independent-test default recall is 51.55%, precision 31.68%.\n\n## Errors\n\nAll errors have `{"error":{"code":"...","message":"...","details":[...]}}`. Validation details contain sanitized location/type/message, never submitted health values or Python exception context. Status codes: 400 malformed/duplicate/non-finite JSON, 413 oversized body, 415 unsupported media type, 422 invalid schema/category/profile/batch limit, 500 safe internal/inference failure, 503 not ready, 404/405 unsupported route/method. Deep valid JSON is rejected by parser or schema, never accepted as a profile. No silent profile fallback. Responses include generated X-Request-ID.\n\n## Operations and compatibility\n\nCORS is configurable with an explicit origin list and defaults to no origins. Debug is false. The model is cached once per process; calls share a prediction lock. Operational logs contain request_id, normalized endpoint, status, latency, model_version, threshold_profile and batch_size, without health payloads/scores. No public SHAP, clinical advice, subgroup thresholds or future-risk endpoint exists. See OpenAPI at /openapi.json and docs at /docs. Changes to category meanings, required structural fields or response semantics require a reviewed contract version.\n\nThis release is **READY FOR LOCAL RESEARCH USE**. Docker/container execution remains PENDING because Docker is unavailable. Controlled deployment requires successful container verification, appropriate client authorization, TLS, rate/concurrency controls and deployment-specific review. External clinical validation is separate.\n'
    (ROOT/'docs/api_contract.md').write_text(contract,encoding='utf-8')
    (ROOT/'docs/model_v2_backlog.md').write_text('# Model v2 research backlog\n\nDocumentation only: none of these changes is implemented in frozen version 1.0.0.\n\n| Topic | Proposed evidence / question |\n| --- | --- |\n| External validation | Evaluate independent populations with prespecified metrics and missingness policies. |\n| Prospective outcomes | Acquire a longitudinal outcome dataset before making any future-risk claim. |\n| Survey weighting | Assess population-oriented estimates using appropriate BRFSS sampling weights/design. |\n| Subgroups | Prespecify age/sex and other adequately sampled subgroup analyses, uncertainty and fairness objectives. |\n| Clinical measurements | Study meaningful measurements only where deployment collection and outcome validity are established. |\n| Threshold cost analysis | Define research/clinical costs, benefits and acceptable error burdens before considering a clinical operating point. |\n| Cross-year BRFSS | Validate fixed definitions and preprocessing on later surveys without optimizing the current test set. |\n| Temporal validation | Use a genuinely held-out time period with prespecified evaluation. |\n| Missingness shifts | Investigate train/validation differences, screening-dependent cholesterol and real-world input availability. |\n| Calibration | Study transportability using independent, appropriately reserved calibration data in a new model version. |\n\nRetain v1.0.0 unchanged. Docker verification, TLS, authorization and rate limiting are deployment tasks, not excuses to tune the model against its test set.\n',encoding='utf-8')
    openapi=create_app().openapi();(OUT/'openapi.json').write_text(json.dumps(openapi,indent=2),encoding='utf-8')
    manifest=json.loads((RELEASE/'release_manifest.json').read_text())
    assert manifest['model_sha256']==MODEL_HASH and manifest['tests_failed']==0 and manifest['test_count']==60
    files=set(json.loads((OUT/'model_integrity.json').read_text())['files_sha256'])
    files.update({'src/__init__.py','src/models/__init__.py','src/data/__init__.py','reports/deployment/model_integrity.json','Dockerfile','.dockerignore','.env.example','requirements-api.txt','requirements-api-test.txt','README.md','docs/api_contract.md','docs/api.md','docs/model_inputs.md','docs/thresholds.md','docs/model_v2_backlog.md','scripts/verify_container.ps1'})
    files.update(p.relative_to(ROOT).as_posix() for directory in ['api','src/inference'] for p in (ROOT/directory).rglob('*.py'))
    assert not any(p.endswith(('.XPT','.npz')) or '/candidates/' in p or p.endswith(('train.csv','validation.csv','test.csv')) for p in files)
    manifest['packaged_files_sha256']={p:sha(ROOT/p) for p in sorted(files)}
    manifest['packaging_scope']='Runtime model/API source, dictionary, integrity/golden fixtures, deployment config and client docs; no respondent data or training caches.'
    (RELEASE/'release_manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
    files.add('release/release_manifest.json');archive=RELEASE/'cardiorisk-api-1.0.0.zip'
    with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED) as output:
        for relative in sorted(files):output.write(ROOT/relative,relative)
    with zipfile.ZipFile(archive) as check:
        assert check.testzip() is None and set(check.namelist())==files
        for p,h in manifest['packaged_files_sha256'].items():assert hashlib.sha256(check.read(p)).hexdigest()==h,p
    (RELEASE/'archive_sha256.txt').write_text(sha(archive)+'  '+archive.name+'\n',encoding='utf-8')
    required=['release/release_manifest.json','reports/deployment/final_deployment_quality_gate.md','reports/deployment/inference_performance.json','reports/deployment/container_verification.md','docs/api_contract.md','docs/model_v2_backlog.md']
    for p in required:assert (ROOT/p).is_file() and (ROOT/p).stat().st_size;print('[PASS]',p)
    print('Release archive verified:',archive.name,'bytes:',archive.stat().st_size,'SHA256:',sha(archive))
if __name__=='__main__':main()
